# ---------------------------------------------------------------------------- ripper
def _canon(name: str) -> str:
    name = name.strip(" .-_:")
    return KNOWN_RIPPERS.get(name.casefold(), name)


# --- vinylrip.py:144
def _a_name(name: str) -> bool:
    words = str(name or "").strip(" .-_:").split()
    return bool(words) and all(w.strip(".").casefold() not in _NOT_A_NAME for w in words)


# --- vinylrip.py:149
def _signed(m) -> bool:
    """A "rip by X" match that names someone: not software or a forum word, and - unless a known
    ripper - not a word in lower case running on into the sentence ("rip by john at ...",
    "rip by Foo using Audacity"): a name ends at punctuation or the line's end."""
    name = m.group(1)
    if not _a_name(name) or any(w.upper() in _NOT_RIPPER for w in name.split()):
        return False
    if name.split()[0].casefold() in KNOWN_RIPPERS:
        return True
    after = m.string[m.end():m.end() + 30]
    if not re.match(r" +[a-z]", after):
        return True                                   # (the name ends at punctuation or the line's end)
    # (a name in capitals running on into a phrase about the rip: "Ripped by Packgrog on a VPI",
    # never into words of a noun - "ripped by Rush fan club")
    return name[:1].isupper() and bool(re.match(r" +(?:on|using|with|at|in|from|for|via|and|to|off)\b", after))


# --- vinylrip.py:166
def _brackets(text):
    return re.findall(r"[\(\[\{]([^\)\]\}]+)[\)\]\}]", str(text or ""))


# --- vinylrip.py:170
def ripper_in_name(folder_name: str) -> str:
    """VIN-3: the ripper a folder name names for sure: a known ripper's name anywhere in its
    brackets ("[Vinyl Rip PBTHAL 24bit 96khz ...]"), or "rip by X". A word in capitals after
    "Vinyl Rip" is only a candidate (caps_in_name): never a catalogue number ("[Vinyl Rip 24bit
    192khz Mercury Price19]": PRICE 19 is the pressing's), a label, a country or a format."""
    for content in _brackets(folder_name):
        for w in re.findall(r"[\w\-]+", content):
            if w.casefold() in KNOWN_RIPPERS:
                return KNOWN_RIPPERS[w.casefold()]
        m = _BY.search(content)
        if m and _signed(m):
            return _canon(m.group(1))
    return ""


# --- vinylrip.py:185
def caps_in_name(folder_name: str) -> str:
    """VIN-3: the name right after "Vinyl Rip" (and before the resolution, the catalogue number,
    a version name or the bracket's end): one word in capitals of 4 to 12 letters ("[Vinyl Rip
    KRONOS 24bit 96khz ...]") or one or two capitalised words ("[Vinyl Rip Fran Solo
    SRM-1-3743]") that are no label, country, format or pressing word - a ripper only where the
    rip notes, a comment or the scans name it too (describe)."""
    for content in _brackets(folder_name):
        m = _VINYL_RIP_WORDS.search(content)
        if not m:
            continue
        words = []
        for w in content[m.end():].split():
            w = w.strip(",;:")
            if not w or _RES_IN_NAME.match(w) or re.search(r"\d", w) or _VERSION_NAME.match(w) or \
                    w in ("Final", "Ultimate", "Definitive", "Flat", "Raw", "Redux", "-", "\u2013") or \
                    (words and (w.upper() in _NOT_RIPPER or w.upper() in _COUNTRY)):
                break                                 # (a label after the name ends it: "Fran Solo Mercury ...")
            words.append(w)
        if not 1 <= len(words) <= 2:
            continue
        if any(w.upper() in _NOT_RIPPER or w.upper() in _COUNTRY or w.casefold() in _NOT_A_NAME for w in words):
            continue
        if len(words) == 1 and re.fullmatch(r"[A-Z]{4,12}", words[0]):
            return words[0]
        if all(re.fullmatch(r"[A-Z][a-z]{1,15}", w) for w in words):
            return " ".join(words)
    return ""


# --- vinylrip.py:214
def version_of(folder_name: str, text: str = "") -> str:
    """VIN-3: a ripper's own name for this transfer of his ("Ultimate Master" beside his "Final
    Master" of one pressing): in the folder name's rip bracket ("Final Master", "Ultimate
    Master", "Redux", "v2" ...), else in the rip notes or comment ("24-bit/96kHz Ultimate Master
    Vinyl Rip", a comment "Final Master"): "<Final|Ultimate|Definitive> Master" only. "" else."""
    for content in _brackets(folder_name):
        if _VINYL_RIP_WORDS.search(content):
            m = _VERSION_NAME.search(content)
            if m:
                return re.sub(r"\s+", " ", m.group(1))
    m = _VERSION_IN_NOTES.search(str(text or ""))
    return re.sub(r"\s+", " ", m.group(1)) if m else ""


# --- vinylrip.py:228
def _split_version(who: str) -> tuple:
    """("PBTHAL", "Ultimate Master") from "PBTHAL Ultimate Master"."""
    m = re.search(r"\s+(" + _VERSION_NAME.pattern[3:-3] + r")$", who or "")
    return (who[:m.start()].strip(), re.sub(r"\s+", " ", m.group(1))) if m else (who or "", "")


# --- vinylrip.py:234
def watermark_ripper(comment_text: str, scan_text: str) -> str:
    """VIN-3: a ripper whose signature in the comment or notes ("US Pressing - Fran Solo,
    Ediciones MMXIV") is printed on the scans too ("SOLO Ediciones" on the labels): "Fran Solo".
    Both the surname and the word after it must be on the scans."""
    scan = str(scan_text or "").casefold()
    if not scan:
        return ""
    for m in re.finditer(r"\b([A-Z][a-z]{1,15}) ([A-Z][a-z]{1,15}), ([A-Z][a-z]{3,15})\b", str(comment_text or "")):
        who, tail = f"{m.group(1)} {m.group(2)}", m.group(3)
        if not _a_name(who) or any(w.upper() in _NOT_RIPPER or w.upper() in _COUNTRY for w in who.split()):
            continue
        if re.search(rf"\b{re.escape(m.group(2).casefold())}\b", scan) and \
                re.search(rf"\b{re.escape(tail.casefold())}\b", scan):
            return who
    return ""


# --- vinylrip.py:251
def _signs(name: str, text: str) -> bool:
    """VIN-3: the notes or comment sign NAME as a rip's - "rip by NAME", "Posted by NAME", "NAME's
    24bit ...", a signature "NAME, Ediciones ..." - not merely mention it ("Cut at Abbey Road",
    "gatefold sleeve", "Mobile Fidelity Sound Lab pressing")."""
    n = re.escape(name)
    text = str(text or "")
    if ripper_in_notes(text).casefold() == name.casefold():
        return True
    return bool(re.search(rf"\b{n}['\u2019]s\s+(?:\d{{2}}\s*-?\s*bit|vinyl|rip|needle)", text, re.I) or
                re.search(rf"(?:^|[-\u2013:]\s*){n}, [A-Z][a-z]{{3,}}", text, re.M))


# --- vinylrip.py:263
def scan_images(folder, limit=3) -> list:
    """The first scans (images) below FOLDER's scan folders, at most LIMIT."""
    out = []
    try:
        for p in sorted(Path(str(folder)).rglob("*")):
            if p.suffix.lower() in (".jpg", ".jpeg", ".png", ".tif", ".tiff", ".webp") and p.is_file() and \
                    p.parent != Path(str(folder)):
                out.append(p)
                if len(out) >= limit:
                    break
    except OSError:
        pass
    return out


